import{A as e,f as t,h as n,t as r}from"./chunks/plugin-vue_export-helper.I53torQa.js";var i=JSON.parse(`{"title":"MoE 负载均衡：训练与推理加速方案综述","description":"梳理 MoE 训练与推理中的专家负载均衡方案，对比 DeepEP、MoonEP、UltraEP、EPLB 与 LPLB 的规划机制、通信接口、框架集成及昇腾支持范围，为方案选型提供依据。","frontmatter":{"title":"MoE 负载均衡：训练与推理加速方案综述","description":"梳理 MoE 训练与推理中的专家负载均衡方案，对比 DeepEP、MoonEP、UltraEP、EPLB 与 LPLB 的规划机制、通信接口、框架集成及昇腾支持范围，为方案选型提供依据。"},"headers":[],"relativePath":"ascend/ecosystem/moe-load-balancing-survey.md","filePath":"ascend/ecosystem/moe-load-balancing-survey.md","lastUpdated":1793934895000}`),a={name:`ascend/ecosystem/moe-load-balancing-survey.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="moe-负载均衡-训练与推理加速方案综述" tabindex="-1">MoE 负载均衡：训练与推理加速方案综述 <a class="header-anchor" href="#moe-负载均衡-训练与推理加速方案综述" aria-label="Permalink to “MoE 负载均衡：训练与推理加速方案综述”">​</a></h1><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to “摘要”">​</a></h2><ul><li>负载均衡已经从「训练时用辅助 loss 让路由更均匀」，演进为<strong>运行时专家复制与再放置</strong> （冗余专家 / 专家迁移），并出现了事实上的公共接口：权重预取 + 梯度归约原语。</li><li>Ascend 侧不是空白：DeepEP 有官方 Ascend 分支，vLLM-Ascend 与 SGLang 都有可用的 EPLB， MindSpeed 提供了训练侧的两条负载均衡路线。</li></ul><h2 id="_1-开源生态方案" tabindex="-1">1. 开源生态方案 <a class="header-anchor" href="#_1-开源生态方案" aria-label="Permalink to “1. 开源生态方案”">​</a></h2><h3 id="_1-1-总览" tabindex="-1">1.1 总览 <a class="header-anchor" href="#_1-1-总览" aria-label="Permalink to “1.1 总览”">​</a></h3><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>项目</th><th>定位</th><th>均衡思路</th><th>硬件</th></tr></thead><tbody><tr><td><a href="https://github.com/deepseek-ai/DeepEP" target="_blank" rel="noreferrer">DeepEP</a> (V2.5)</td><td>EP dispatch / combine 通信库</td><td>提供冗余专家的<strong>权重预取 + 梯度归约原语</strong>，规划交给调用方</td><td>NVIDIA Hopper+</td></tr><tr><td><a href="https://github.com/deepseek-ai/DeepEP-Ascend" target="_blank" rel="noreferrer">DeepEP-Ascend</a></td><td>同上，官方昇腾分支</td><td>同上，但 <code>lb_*</code> 内核尚未实现</td><td>Ascend 950 (A5)</td></tr><tr><td><a href="https://github.com/MoonshotAI/MoonEP" target="_blank" rel="noreferrer">MoonEP</a></td><td>EP 通信库</td><td><strong>在线规划动态冗余专家</strong>，每 rank 恒定 S×K，零拷贝</td><td>NVIDIA（Zhenwu PPU 待定）</td></tr><tr><td><a href="https://github.com/Dots-Infra/UltraEP" target="_blank" rel="noreferrer">UltraEP</a></td><td>负载均衡库（v1.0.0）</td><td>用<strong>逐 microbatch 精确 post-gating 负载</strong>实时复制 + 重路由</td><td>NVIDIA SM90 / SM100</td></tr><tr><td><a href="https://github.com/deepseek-ai/EPLB" target="_blank" rel="noreferrer">EPLB</a></td><td>算法本体（DeepSeek 开源）</td><td>冗余专家 + 分层 / 全局打包，周期性重排布局</td><td>与硬件无关（纯算法）</td></tr><tr><td><a href="https://github.com/deepseek-ai/LPLB" target="_blank" rel="noreferrer">LPLB</a></td><td>EPLB 的续作（DeepSeek 开源）</td><td>固定冗余拓扑上逐 batch 解 LP 重路由 token</td><td>CUDA + cuSolverDx / cuBLASDx</td></tr><tr><td><a href="https://github.com/vllm-project/vllm" target="_blank" rel="noreferrer">vLLM</a> / <a href="https://github.com/vllm-project/vllm-ascend" target="_blank" rel="noreferrer">vllm-ascend</a></td><td>推理框架</td><td>EPLB 控制面 + 权重重排；Ascend 版有独立 movement 适配层</td><td>NVIDIA / Ascend A2、A3、950</td></tr><tr><td><a href="https://github.com/sgl-project/sglang" target="_blank" rel="noreferrer">SGLang</a></td><td>推理框架</td><td>EPLB 多算法路径（含集成 LPLB 求解器、waterfill 打包）</td><td>NVIDIA / Ascend A2、A3</td></tr><tr><td><a href="https://github.com/Ascend/MindSpeed" target="_blank" rel="noreferrer">MindSpeed</a></td><td>昇腾训练加速库</td><td><strong>专家迁移</strong> + <strong>动态热专家广播</strong></td><td>Ascend</td></tr><tr><td><a href="https://github.com/NVIDIA/Megatron-LM" target="_blank" rel="noreferrer">Megatron-LM</a></td><td>训练框架</td><td>aux / seq / global aux loss、sinkhorn、aux-loss-free bias</td><td>NVIDIA</td></tr></tbody></table></div><h3 id="_1-2-ep-通信库与-dispatcher-集成" tabindex="-1">1.2 EP 通信库与 dispatcher 集成 <a class="header-anchor" href="#_1-2-ep-通信库与-dispatcher-集成" aria-label="Permalink to “1.2 EP 通信库与 dispatcher 集成”">​</a></h3><p><strong>定位</strong>：DeepEP 只解决 EP 的 dispatch / combine 通信，并把冗余专家的权重预取与梯度归约做成原语； <strong>它不做负载均衡决策</strong>——复制谁、复制到哪、token 怎么重路由，全部由调用方给出。</p><p><strong>DeepEP V2.5</strong> 做了较大重构：移除 NVSHMEM 依赖、改用 <strong>NCCL Gin 后端</strong>，通信内核通过 <strong>DeepJIT</strong> 在运行时编译，dispatch / combine 统一进 <code>EPBuffer</code>。 与负载均衡最相关的是新增的两个原语：</p><ul><li><code>EPBuffer.lb_prefetch_weights(redundant_expert_weights, expert_weights, redundancy_mapping)</code>： 在专家计算前把原专家权重（可含量化 scale）推到冗余槽位；</li><li><code>EPBuffer.lb_reduce_grads(redundant_expert_grads, expert_grads, redundancy_mapping)</code>： 在反向把冗余专家的 FP32 梯度跨 NVLink 累加回原专家梯度。</li></ul><p>调用方提供 <code>[num_nvlink_ranks, num_redundant_experts]</code> 的 int32 副本映射，并负责把 token 重路由到 被选中的专家实例。README 说明这两个原语是为支持 MoonEP / UltraEP 的专家复制路线而暴露的—— 三家因此收敛到同一套接口语义（前向把主专家权重推到副本、反向把副本梯度归约回主专家； UltraEP 明确说明副本不维护优化器状态），对应的实现见 3.2.3、3.3.4 与 3.4.5。</p><p>框架侧的 dispatcher 生态已相当统一：Megatron-LM 的 FlexDispatcher 支持 <code>deepep</code> / <code>deepepv2</code> / <code>hybridep</code> 三个后端；vLLM 已落地 MoonEP 后端 （<code>vllm/model_executor/layers/fused_moe/experts/moonep_experts.py</code>， 但其 <code>_supports_current_device()</code> 断言 <code>current_platform.is_cuda()</code>，即 <strong>CUDA-only</strong>）。</p><h3 id="_1-3-负载均衡控制面" tabindex="-1">1.3 负载均衡控制面 <a class="header-anchor" href="#_1-3-负载均衡控制面" aria-label="Permalink to “1.3 负载均衡控制面”">​</a></h3><p><strong>EPLB（DeepSeek 开源）</strong>：核心是 <code>eplb.rebalance_experts(weight, num_replicas, num_groups, num_nodes, num_gpus)</code>， 按「节点数能否整除专家组数」在分层与全局两种策略间切换，只输出 <code>phy2log / log2phy</code> 映射， 与硬件无关，因此 Ascend 侧框架可直接复用该算法。算法步骤与工程约束见 3.1。</p><p><strong>LPLB（DeepSeek 开源，EPLB 的续作）</strong>：在 EPLB 给出的冗余拓扑之上逐 batch 解线性规划重分配 token， 补上 EPLB 无法应对的 batch 内抖动；每个被选中的专家最多复制一份。模型、拓扑与限制见 3.2。</p><p><strong>vLLM</strong>：核心是把 EPLB 拆成三层——控制面（<code>EplbState</code> + policy 决定布局与何时换）、 数据面（fused MoE 把逻辑专家查表映射到本卡物理专家并记录实际执行的专家）、 搬运面（后台 worker 搬迁量化专家权重），从而在服务过程中不停机换布局。 开关为 <code>--enable-eplb --eplb-config &#39;{...}&#39;</code>，配置含 <code>window_size / step_interval / num_redundant_experts / use_async / policy / communicator</code>， 其中 <code>communicator</code> 可选 <code>torch_nccl / torch_gloo / pynccl / nixl</code>。 实现位于 <code>vllm/distributed/eplb/</code>（state + communicator + migration_scheduler + async_worker + rebalance_execute）。</p><p><strong>SGLang</strong>：把 EPLB 做成<strong>多算法可选</strong>的统一入口，并把 LPLB 作为其中一条求解路径集成进来。 <code>python/sglang/srt/eplb/</code> 下同时提供多条算法路径： <code>eplb_algorithms/{deepseek,deepseek_vec,elasticity_aware}.py</code>、<code>lplb_solver.py</code>、<code>waterfill.py</code> 以及 expert distribution recorder 与 simulator。其中 <code>lplb_solver.py</code> 即对上述 LPLB 的集成 （各 rank all-reduce 全局计数后各自独立求解同一个 LP，不需要广播映射）； 但源码注释指出该路径只在 DeepSeek-v2 系列上安全（其它家族的 empty-rank 路径会死锁）。</p><p><strong>MindSpeed（Ascend 训练）</strong>：把负载均衡拆成两条可独立启用的路线——<strong>搬参数</strong>（专家迁移） 与<strong>搬 token</strong>（动态热专家广播），前者改变专家位置、后者改变 token 落点：</p><ul><li><strong>专家迁移</strong>（<code>mindspeed/core/transformer/moe/expert_placement/</code>）： EMA 预测专家负载（θ=0.9）→ DP 域 all-reduce 对齐 → 贪心 / DP / 混合打包 → 迁移专家参数<strong>与优化器一/二阶动量</strong>；细粒度控制器以变异系数至少下降 0.08 为门槛决定 每层是否迁移，默认 <code>expert_placement_freq=50</code>。支持分布式优化器、参数副本复用与 <code>tp_extend_ep</code>。</li><li><strong>动态热专家广播</strong>（<code>balanced_moe</code>，文档称「数参互寻」）： 识别热专家子集后跨 EP 节点广播其参数，把原本发往远端热专家的 token 改为本地计算， 并按 microbatch 精细调度以掩盖通信。限制较强：必须同时开启 <code>--moe-fb-overlap</code> 与 <code>--moe-grouped-gemm</code>，仅支持 <code>alltoall</code> 分发器与 Dropless 模式， 且源码明确说明<strong>不保证二进制对齐</strong>（DeepSeek-V3 减层 4 机 A3 场景 loss 误差 &lt; 1%）。</li></ul><p><strong>Megatron-LM</strong>：思路是从<strong>损失函数侧</strong>抑制不均衡，并把 token dispatcher 做成可替换后端， 是训练侧路由均衡的基准。提供 <code>aux_loss / seq_aux_loss / global_aux_loss / sinkhorn / aux-loss-free(expert bias) / none</code> 六种策略，并配合 MoE parallel folding（解除 EP ≤ DP 限制）、FP8 训练与分布式检查点。</p><h3 id="_1-4-ascend-支持情况" tabindex="-1">1.4 Ascend 支持情况 <a class="header-anchor" href="#_1-4-ascend-支持情况" aria-label="Permalink to “1.4 Ascend 支持情况”">​</a></h3><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>组件</th><th>Ascend 支持</th><th>形态与证据</th><th>边界与限制</th></tr></thead><tbody><tr><td>DeepEP</td><td>✅ 官方分支</td><td><code>DeepEP-Ascend</code>：Ascend C 内核走 HCCL/HCOMM + UBMEM + URMA，DeepJIT 运行时编译，<code>EPBuffer</code> API 与 NVIDIA V2.5 对齐</td><td>仅在 <strong>Ascend 950DT + CANN 9.2.0</strong> 验证；EP 需 <code>do_expand=True</code>、<code>do_handle_copy=False</code>；路由索引固定 int64；不支持显式 RDMA SL / QP 配置；<strong><code>lb_prefetch_weights</code> / <code>lb_reduce_grads</code> 内核尚未实现</strong>；PP / Engram / Bucket 为实验特性</td></tr><tr><td>SGLang</td><td>✅ A2 / A3</td><td>NPU 后端含 <code>hardware_backend/npu/moe/*</code>、<code>moe_runner/ascend.py</code>、<code>token_dispatcher/ascend_tp.py</code>；<code>--moe-a2a-backend</code> 可选 <code>none / deepep / ascend_fuseep</code>（fuseep 与 EPLB 互斥）；EPLB 参数在昇腾支持矩阵中逐项标注 A2/A3</td><td>昇腾上使用的不是官方 DeepEP，而是 <a href="https://github.com/sgl-project/sgl-kernel-npu" target="_blank" rel="noreferrer">sgl-kernel-npu</a> 提供的 <strong>DeepEP 兼容替代库</strong>；<code>--eplb-algorithm</code> 目前为 <code>auto / deepseek</code></td></tr><tr><td>vLLM</td><td>✅ A2 / A3 / 950</td><td><code>vllm-ascend</code> 有完整 EPLB：MRv2 复用上游控制面、Ascend 侧补 HIXL（默认）/ Gloo movement 适配与 <code>load_collection_phase</code>；MRv1 保留 legacy 动态 / 录制 / 静态模式；策略含 default / stair / flashlb / swift_balancer / random</td><td><strong>A2 不支持冗余专家</strong>；950PR/DT 上 W4A8MXFP4、W4A16MXFP4 等量化格式不支持 EPLB；W4A16/MXFP 系列整体被拒；需按目标模型与拓扑验证精度</td></tr><tr><td>MindSpeed</td><td>✅ 原生</td><td>训练侧覆盖最全：<code>alltoall / allgather / alltoall_seq / mc2 / fb_overlap / gmm / tp_extend_ep</code> 分发与重叠；MC2 用 <code>torch_npu.npu_alltoallv_gmm</code>、<code>npu_gmm_alltoallv</code> 融合通信与 GMM；另有 <code>npu_moe_token_permute/unpermute</code> CANN 算子与 <code>moe_fix_router</code></td><td>balanced_moe 的限制见 2.3；expert migration 支持分布式优化器与参数副本复用</td></tr><tr><td>MoonEP / UltraEP</td><td>❌</td><td>二者均为 NVIDIA-only（UltraEP 依赖 NVSHMEM，仅 SM90/SM100；MoonEP 仅覆盖 NVLink 域）</td><td>—</td></tr><tr><td>Megatron-LM</td><td>❌ 直接支持</td><td>硬件说明中 DeepEP 仅列出 H100 / B200</td><td>Ascend 对应生态为 MindSpeed</td></tr></tbody></table></div><p>两点需要特别提醒：</p><ol><li>DeepEP-Ascend 的性能数据来自 DeepSeek 手中的 <strong>PoC HDK</strong>，公开的 Q3 商用 HDK 计划在 2026-10-15 前后发布，且要求 Ascend 950 + UBMEM / UBC_CTP 通道。 也就是说该方案<strong>目前不能直接用于 910B/A2 或 910_93/A3</strong>；A2/A3 实际依赖 CANN / torch_npu 算子底座，加上 MindSpeed 或 vllm-ascend / SGLang 各自的路径。</li><li>昇腾自研推理引擎 MindIE（主要在 GitCode 维护）本次抓取被拒（HTTP 403）， 其 MoE 均衡能力<strong>未经核实</strong>，本文不作结论。</li></ol><hr><h2 id="_2-重点方案解析-eplb、lplb、moonep-与-ultraep" tabindex="-1">2. 重点方案解析：EPLB、LPLB、MoonEP 与 UltraEP <a class="header-anchor" href="#_2-重点方案解析-eplb、lplb、moonep-与-ultraep" aria-label="Permalink to “2. 重点方案解析：EPLB、LPLB、MoonEP 与 UltraEP”">​</a></h2><p>本部分基于逐行阅读源码、官方设计文档与论文，覆盖四个方案的算法步骤、不变量、求解器实现与调参项。</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th></th><th>EPLB</th><th>LPLB</th><th>MoonEP</th><th>UltraEP</th></tr></thead><tbody><tr><td>核心思想</td><td>用历史负载周期性<strong>重排专家位置</strong></td><td>在固定冗余拓扑上逐 batch <strong>调 token 流量</strong></td><td>让每 rank <strong>恒定收 <code>S×K</code></strong>，消除负载敏感性</td><td>逐 microbatch 按<strong>精确负载实时复制</strong></td></tr><tr><td>开源方</td><td>DeepSeek</td><td>DeepSeek</td><td>Moonshot AI</td><td>北大 + 小红书 + 上海 AI Lab</td></tr><tr><td>负载来源</td><td>历史窗口统计（移动平均）</td><td>历史统计（布局）+ 当前 batch（重路由）</td><td>当前层的精确路由</td><td><strong>当前 microbatch 的精确 post-gating 负载</strong></td></tr><tr><td>决策时机</td><td>周期性、全局重排</td><td>布局周期性 + 每 batch 解 LP</td><td>每层每次</td><td>每层每 microbatch</td></tr><tr><td>是否移动 token</td><td>❌ 只改 expert 布局</td><td>✅ 固定拓扑上重路由</td><td>✅ 重路由 + 动态副本</td><td>✅ 重路由 + 动态副本</td></tr><tr><td>副本数</td><td>任意（<code>num_replicas</code>）</td><td><strong>每专家最多 1 个副本</strong>（<code>assert max_logcnt == 2</code>）</td><td>受 prefetch 池 <code>epn</code> 限制</td><td>受每 rank 预留 slot 数限制</td></tr><tr><td>硬件</td><td>无（纯 CPU 算法）</td><td>CUDA + cuSolverDx / cuBLASDx</td><td>NVIDIA + NVLink multicast</td><td>NVIDIA SM90 / SM100 + NVSHMEM</td></tr><tr><td>许可证</td><td>MIT</td><td>MIT</td><td>MIT</td><td>README 标注 MIT</td></tr></tbody></table></div><h3 id="_2-1-eplb-130-行定义清楚问题边界" tabindex="-1">2.1 EPLB：130 行定义清楚问题边界 <a class="header-anchor" href="#_2-1-eplb-130-行定义清楚问题边界" aria-label="Permalink to “2.1 EPLB：130 行定义清楚问题边界”">​</a></h3><p><strong>核心思想</strong>：不做 token 层面的干预，只用<strong>历史负载统计</strong>周期性地重新摆放专家——热点专家复制多份， 再用 LPT 装箱把副本尽量均匀地铺到各 GPU（节点内优先，以利用 group-limited routing）。 由于只改「逻辑专家 → 物理专家」的落点，路由与计算语义完全不变；代价是布局决策依赖负载平稳性， 且重排通常需要停世界。它解决的是<strong>静态不均衡</strong>。</p><p>整个仓库只有一个 <code>eplb.py</code>，对外只导出 <code>rebalance_experts</code>，内部由三个函数构成。</p><h4 id="_2-1-1-三个核心函数" tabindex="-1">2.1.1 三个核心函数 <a class="header-anchor" href="#_2-1-1-三个核心函数" aria-label="Permalink to “2.1.1 三个核心函数”">​</a></h4><p><strong><code>balanced_packing(weight, num_packs)</code>：LPT 贪心装箱。</strong> 输入 <code>[X, n]</code>（X 层、n 个对象）， 要求每个 pack 恰好装 <code>n/m</code> 个对象，目标是最小化各 pack 的权重极差。 实现是标准 Longest-Processing-Time：按权重降序排，每个对象丢给「还有名额且当前最轻」的 pack。 两点实现细节：</p><ul><li>有硬约束 <code>assert num_groups % num_packs == 0</code>，<strong>必须整除</strong>；</li><li><code>groups_per_pack == 1</code> 时直接退化为恒等映射（省掉排序与循环）。</li></ul><p><strong><code>replicate_experts(weight, num_phy)</code>：逐个加副本。</strong> 从 <code>logcnt=1</code> 出发， 循环 <code>num_phy - num_log</code> 次，每次取 <code>(weight / logcnt).max()</code> 的专家作为下一个冗余专家的宿主， 并令该专家 <code>logcnt += 1</code>。即「当前平均负载最高的专家优先再复制一份」，朴素但对负载估计不敏感。</p><p><strong><code>rebalance_experts_hierarchical(...)</code>：三步走。</strong></p><ol><li>把专家组按负载装箱到节点（<code>balanced_packing(tokens_per_group, num_nodes)</code>）；</li><li>在节点内做 <code>replicate_experts</code>（目标份额为 <code>num_physical_experts // num_nodes</code>）；</li><li>把物理专家 LPT 装箱到 GPU（<code>balanced_packing(tokens_per_phy, num_gpus // num_nodes)</code>）。</li></ol><p>动机是 group-limited routing：同组专家尽量落在同节点，跨节点流量最小。</p><h4 id="_2-1-2-一个实现上的小聪明" tabindex="-1">2.1.2 一个实现上的小聪明 <a class="header-anchor" href="#_2-1-2-一个实现上的小聪明" aria-label="Permalink to “2.1.2 一个实现上的小聪明”">​</a></h4><p>所谓「全局策略」并没有另写一套实现，而是在 <code>rebalance_experts</code> 里判断 <code>num_groups % num_nodes == 0</code>：成立走分层策略；不成立则<strong>把整机当成一个组一个节点</strong> （<code>num_groups=1, num_nodes=1</code>）再调一次同一个函数，分层逻辑自动退化为全局装箱。</p><h4 id="_2-1-3-工程约束-readme-未提及" tabindex="-1">2.1.3 工程约束（README 未提及） <a class="header-anchor" href="#_2-1-3-工程约束-readme-未提及" aria-label="Permalink to “2.1.3 工程约束（README 未提及）”">​</a></h4><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>约束</th><th>影响</th></tr></thead><tbody><tr><td>全流程在 <strong>CPU</strong> 上跑（<code>weight.float().cpu()</code>），一次性计算所有层</td><td>适合离线 / 周期性调用，不适合热路径</td></tr><tr><td>复杂度约 <code>O(L·(E log E + 冗余数·E))</code>（按代码估算）</td><td>256 专家量级可忽略</td></tr><tr><td>多重整除断言（专家数/组数/节点数/GPU 数）</td><td>不满足拓扑时直接 assert 失败，需调用方保证</td></tr><tr><td>只输出映射（<code>phy2log</code>、<code>log2phy</code> 带 <code>-1</code> 填充、<code>logcnt</code>）</td><td><strong>完全不碰 token</strong>：改的是逻辑→物理落点，无法应对同一专家在 batch 内忽冷忽热</td></tr></tbody></table></div><p>最后一点正是 LPLB 要补的洞。</p><h3 id="_2-2-lplb-把静态布局变成每-batch-的-lp-重路由" tabindex="-1">2.2 LPLB：把静态布局变成每 batch 的 LP 重路由 <a class="header-anchor" href="#_2-2-lplb-把静态布局变成每-batch-的-lp-重路由" aria-label="Permalink to “2.2 LPLB：把静态布局变成每 batch 的 LP 重路由”">​</a></h3><p><strong>核心思想</strong>：把 EPLB 的一步拆成两步——<strong>复制谁</strong>仍由 EPLB 按历史负载决定（静态、周期性）， <strong>每个被复制专家分到多少 token</strong> 则由当前 batch 的负载解一个线性规划（动态、逐 batch）。 冗余专家与其原专家之间的连接被抽象成「边」，边容量即分给该副本的 token 数， 于是「均衡」变成「在边容量约束下最小化 EP 组内最大负载」。 它补的是 EPLB 的短板：<strong>batch 内抖动</strong>。</p><p><code>deepseek-ai/LPLB</code> 是 EPLB 的续作，也是 SGLang <code>lplb_solver.py</code> 的来源。</p><h4 id="_2-2-1-图模型" tabindex="-1">2.2.1 图模型 <a class="header-anchor" href="#_2-2-1-图模型" aria-label="Permalink to “2.2.1 图模型”">​</a></h4><ul><li><strong>边</strong>：冗余专家 ↔ 其原专家（由拓扑矩阵 <code>r2o</code> 决定）；</li><li><strong>边容量</strong>：本 batch 分给该冗余专家的 token 数，即该边允许的最大 token 流；</li><li><strong>求解目标</strong>：在边容量约束下重分配 token，最小化 EP 组内最大负载。</li></ul><h4 id="_2-2-2-两段式分工" tabindex="-1">2.2.2 两段式分工 <a class="header-anchor" href="#_2-2-2-两段式分工" aria-label="Permalink to “2.2.2 两段式分工”">​</a></h4><p>谁被复制由 EPLB 决定（使用「只 reorder、不 replication」的变体），复制后的每 batch token 去向由 LP 决定。 <code>Planner.update_redundancy_mapping</code> 的顺序很能说明问题：</p><ol><li>先用 <code>rebalance_experts</code>（<code>num_replicas == 逻辑专家数</code>，即不做复制）得到基础布局；</li><li>按 workload 历史在每 device 内对专家降序排序；</li><li>每 device 取前 <code>combined_redundant_experts * num_redundants</code> 个专家作为「待复制」集合；</li><li>按拓扑矩阵 <code>r2o</code> 把副本挂到对端 rank，构建 <code>log2phy</code> 时保证原始专家排在副本之前；</li><li>最后 <code>assert max_logcnt == 2</code> —— <strong>每个被选中的专家只复制一份</strong>。</li></ol><p>拓扑 <code>r2o</code> 的形状是 <code>[group_size, num_redundants]</code>，并要求：每 rank 冗余专家数相同； 第 i 个冗余专家必须是另一个 rank 上第 i 个专家的副本——这让<strong>每个冗余专家恰好被两个 rank 共享</strong>。 仓库预置三类拓扑：</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>拓扑</th><th>要求</th><th>适用</th></tr></thead><tbody><tr><td>Cube</td><td>每卡 ≥ 2 专家，保留对角边</td><td>8 卡 EP 子组内均衡，不牺牲跨节点通信</td></tr><tr><td>Hypercube</td><td>16 卡，去掉对角边</td><td>跨 16 卡专家并行</td></tr><tr><td>Torus</td><td>每卡 ≥ 2 专家，编内 + 编外各一邻居</td><td>全局均衡，但跨节点效率低于 Cube</td></tr></tbody></table></div><p>自定义拓扑即修改 <code>r2o</code> 矩阵。</p><h4 id="_2-2-3-实现与集成" tabindex="-1">2.2.3 实现与集成 <a class="header-anchor" href="#_2-2-3-实现与集成" aria-label="Permalink to “2.2.3 实现与集成”">​</a></h4><ul><li>求解器是<strong>单 SM 的 Interior Point Method</strong>，线性代数走 NVIDIA 的 cuSolverDx / cuBLASDx （需先执行 <code>download-mathdx.sh</code>）；示例中按 <code>N_SMS = 100</code>（<strong>SM 数</strong>，与上文「约 100 µs」的 求解延迟无关）调用。</li><li>实时负载统计可来自 <code>torch.distributed</code>，也可直接复用 <strong>DeepEP buffer 的内部通信器</strong> （用 NVLINK + NVSHMEM 替代 <code>allreduce</code>）。</li><li>对外接口：<code>count_workload(idx, n_sms)</code> → <code>solve_probs(workload, avail_counter)</code> → <code>run(indices, avail_counter, N_SMS)</code> 返回重定向后的物理专家索引；<code>init_from_deep_ep(buffer)</code> 可初始化。</li></ul><h4 id="_2-2-4-作者自陈的限制-比宣传更有参考价值" tabindex="-1">2.2.4 作者自陈的限制（比宣传更有参考价值） <a class="header-anchor" href="#_2-2-4-作者自陈的限制-比宣传更有参考价值" aria-label="Permalink to “2.2.4 作者自陈的限制（比宣传更有参考价值）”">​</a></h4><ol><li>只均衡 token 总数，<strong>不考虑 grouped GEMM 耗时对 token 数的非线性</strong>，可能次优；</li><li>求解约 <strong>100 µs</strong>（跨节点更久），小 batch 下不可忽略；</li><li><strong>极端全局不均衡时可能不如 EPLB</strong>——因为 LPLB 避免把多个副本给同一原专家，而 EPLB 会；</li><li>仍是早期研究阶段，性能收益「尚在评估」。</li></ol><h3 id="_2-3-moonep-用「完美均衡」换掉负载敏感性" tabindex="-1">2.3 MoonEP：用「完美均衡」换掉负载敏感性 <a class="header-anchor" href="#_2-3-moonep-用「完美均衡」换掉负载敏感性" aria-label="Permalink to “2.3 MoonEP：用「完美均衡」换掉负载敏感性”">​</a></h3><p><strong>核心思想</strong>：不去追赶负载，而是<strong>消除负载的不确定性</strong>——让每个 rank 在每层恒定收到 <code>S×K</code> 个 token， 与路由偏斜完全无关。做法是在线规划出若干冗余专家实例：把热点专家的 token 直接写到目的 rank 的 专家分组位置上（零拷贝），并把该专家的权重预取过去；反向再把副本梯度归约回主专家。</p><p>这样通信与迭代时间对 <code>maxvio = max_e(T_e/T̄) − 1</code> 基本不敏感，代价是额外的规划与权重预取内核。</p><h4 id="_2-3-1-规划算法" tabindex="-1">2.3.1 规划算法 <a class="header-anchor" href="#_2-3-1-规划算法" aria-label="Permalink to “2.3.1 规划算法”">​</a></h4><p>规划逻辑在 56 KB 的 CuTe DSL 内核里，但仓库提供了等价的 Torch 参考实现 （<code>tests/planning_reference.py</code>），读它更高效。步骤：</p><ol><li>all-gather 各 rank 的 <code>tokens_per_expert</code> → <code>tpe[R, E]</code>，得到全局每专家 token 数 <code>expert_count</code>；</li><li>按 home group（每 rank 一段连续的 <code>epn = E/R</code> 个专家）求和得 <code>group_tokens[h]</code>；</li><li>计算 <code>balance = group_tokens − CAP</code>，<code>CAP = S×K</code> 是每 rank 的接收容量； 因总量守恒 <code>sum(balance) == 0</code>，正值表示该 home group 过载、负值表示该 rank 有余量；</li><li><strong>贪心迁移</strong>：反复取 <code>h = balance.argmax()</code>、<code>u = balance.argmin()</code>，迁移 <code>-balance[u]</code> 个 token， 直到没有 group 过载（策略总是把接收方填满）；</li><li>把 quota 落到具体专家：「最大远端 quota × 剩余 token 最多的本地专家」逐轮取 <code>take = min(rem, quota)</code>，得到 <code>alloc[e, d]</code>（专家 e 有多少 token 落到目的 rank d）；</li><li>断言两条不变量：<code>alloc.sum(dim=1) == expert_count</code>（逐专家守恒）、 <code>alloc.sum(dim=0) &lt;= CAP</code>（每 rank 不超容量）。</li></ol><h4 id="_2-3-2-物理布局与关键不变量" tabindex="-1">2.3.2 物理布局与关键不变量 <a class="header-anchor" href="#_2-3-2-物理布局与关键不变量" aria-label="Permalink to “2.3.2 物理布局与关键不变量”">​</a></h4><p>目的 rank <code>d</code> 上的 token 排布是：</p><ul><li><code>[0, epn)</code>：<strong>本 rank 自己的本地专家</strong>（<code>local_start = d * epn</code>）；</li><li><code>[epn, 2*epn)</code>：<strong>远端专家的 prefetch 槽位</strong>（由 <code>experts_to_copy[d, b]</code> 指定）。</li></ul><p>由此得到 MoonEP 最关键的约束：<strong>每个目的 rank 最多接收一个远端 home group 的专家</strong> （参考实现里有 <code>len(remote_experts) &gt; epn</code> 的断言）。这让每 rank 每投影的 prefetch 池大小刚好等于 <code>epn</code>， 且该池是<strong>进程级、跨层共享</strong>的——额外物理成本是总共 <code>epn</code> 个专家权重，而不是每层一份。</p><p>另外：<code>cu_seqlens</code> 按 <code>token_padding</code>（benchmark 用 128）对齐，padding 行由 dispatch 的 zero warp 清零 （<code>zero_fill_ranges</code>）；<code>dst</code> 把目的 rank 与段内偏移打包进一个 int32 （<code>dst[i] = dest * NvS + base_off + seg_pos</code>），重复项用负数编码，并生成 <code>dup_groups / dup_loffs / dup_counts</code> 三张去重表。</p><h4 id="_2-3-3-内核与内存" tabindex="-1">2.3.3 内核与内存 <a class="header-anchor" href="#_2-3-3-内核与内存" aria-label="Permalink to “2.3.3 内核与内存”">​</a></h4><ul><li>规划是<strong>一次 cooperative grid launch 的 CuTe DSL 内核</strong>：<code>num_sms</code> 个 block 在一次启动里跑完 Phase A/B/C/D；块间用软件 grid barrier，跨 rank 用 NVLink <code>meta_buf</code> 上的<strong>系统级原子自复位屏障</strong>； 大量使用 warp 级 argmax / scan 原语。</li><li>打包编码位宽是<strong>常量而非推导</strong>：<code>RANK_BITS = 7</code>、<code>KIDX_BITS = 7</code>，注释写明「2^7 = 128 足够覆盖当前主流 EP 设置」； 去重构建用 <code>DEDUP_BUILDER_WARPS = 4</code>（注释解释了单 warp 是延迟受限、4 warp 是收益拐点）。</li><li>内存走 CUDA VMM（<code>nvl_dist_alloc</code> / <code>nvl_dist_map</code>），跨 rank 共享可用 fabric handle 或 POSIX fd （<code>MOONEP_MEM_HANDLE_TYPE=auto|fabric|fd</code>），并使用 NVLink multicast（<code>nvl_multicast_*</code>）。 <code>zero_copy=True</code> 时 dispatch 直接返回通信缓冲的 view，专家 FFN 原地读写，没有边界拷贝。</li><li>去重表的顺序由 builder 的 <code>atomicAdd</code> 决定、<strong>不保证稳定</strong>，参考实现明确要求测试比对 「组的集合」而不是元素顺序——这是个容易踩的坑。</li></ul><h4 id="_2-3-4-训练侧的四条路径" tabindex="-1">2.3.4 训练侧的四条路径 <a class="header-anchor" href="#_2-3-4-训练侧的四条路径" aria-label="Permalink to “2.3.4 训练侧的四条路径”">​</a></h4><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>方向</th><th>调用</th><th>说明</th></tr></thead><tbody><tr><td>前向</td><td><code>dispatch</code> → <code>prefetch_weight</code> → 专家 GEMM → <code>combine</code></td><td>prefetch 把原专家权重（可含量化 scale）推到冗余槽位</td></tr><tr><td>dispatch 反向</td><td><code>combine(plan)</code></td><td>把 K 份梯度求和回 token-major</td></tr><tr><td>combine 反向</td><td><code>dispatch(grad, plan)</code></td><td>复用 plan，跳过规划与预取</td></tr><tr><td>权重梯度</td><td><code>reduce_grad</code></td><td>把冗余专家 FP32 梯度跨 NVLink 累加回原专家</td></tr></tbody></table></div><h4 id="_2-3-5-benchmark-方法学-值得借鉴" tabindex="-1">2.3.5 Benchmark 方法学（值得借鉴） <a class="header-anchor" href="#_2-3-5-benchmark-方法学-值得借鉴" aria-label="Permalink to “2.3.5 Benchmark 方法学（值得借鉴）”">​</a></h4><p><code>benchmarks/bench_vs_deepep.py</code> 的对齐做得很克制：</p><ul><li>两库使用<strong>完全相同的路由矩阵</strong>（共享 seed 1234）、相同输入张量与生成器 seed；</li><li>相同 SM 预算（32）、相同 <code>expert_alignment / token_padding</code>（128）；</li><li>相同计时框架（eager CUDA event、back-to-back、warmup 20 / iters 50、跨 rank 取均值）；</li><li>只对齐 <strong>DeepEP v2 的 <code>do_expand=True</code></strong> 路径，并说明 DeepEP v1 因不做融合 permute 而不参与比较；</li><li><code>grad_reduce</code> <strong>不计入</strong>（可被后续计算掩盖、不在 MoE 关键路径）；</li><li>带宽口径统一为 <code>S*K*H*2 / t</code>（逻辑 payload 字节）。</li></ul><p>局限：README 的性能结论是<strong>图示 + 定性</strong>（通信时间随 maxvio 基本持平、DeepEP v2 随最热 rank 退化）， <strong>没有给绝对数字</strong>，引用时需注意；benchmark 仅单节点（<code>ep == world size</code>）； 设备仅列 NVIDIA GPU（Zhenwu PPU 标注待定）；强依赖 NVLink multicast 与 fabric handle。</p><h3 id="_2-4-ultraep-把「精确负载-实时」做成生产系统" tabindex="-1">2.4 UltraEP：把「精确负载 + 实时」做成生产系统 <a class="header-anchor" href="#_2-4-ultraep-把「精确负载-实时」做成生产系统" aria-label="Permalink to “2.4 UltraEP：把「精确负载 + 实时」做成生产系统”">​</a></h3><p><strong>核心思想</strong>：赌「算得起」——<strong>在每个 microbatch 的每一层，用精确的 post-gating 负载实时决定 复制哪些专家、token 如何重路由</strong>，完全不依赖历史预测。为此它不分别求解「布局」与「重路由」， 而是直接求解重路由后每个专家实例收到的负载（quota），并把复制流量限制在 scale-up 域内、 用跨层复用的副本缓冲把显存成本摊薄。</p><p>论文（arXiv 2606.04101）给出的理由是：预测式方法（EPLB/LPLB）的有效性<strong>取决于专家负载的平稳性</strong>， 而今天的细粒度 MoE 负载往往高度动态，预测误差会直接变成 straggler。</p><h4 id="_2-4-1-专家状态布局与内存" tabindex="-1">2.4.1 专家状态布局与内存 <a class="header-anchor" href="#_2-4-1-专家状态布局与内存" aria-label="Permalink to “2.4.1 专家状态布局与内存”">​</a></h4><ul><li>每 EP rank 在主专家（main / master experts）之外预留<strong>固定数量</strong>的冗余专家槽位；</li><li>冗余专家<strong>不维护优化器状态</strong>：它们的梯度在反向实时归约回主专家，优化器只更新主专家；</li><li>冗余专家的权重与梯度缓冲<strong>跨层复用</strong>——这是可行性的关键。Qwen3-235B 上， 每 rank 单个冗余槽的额外显存从 <strong>9.9 GB 降到 108 MB</strong>；</li><li>运行期不做动态显存分配，声称不改变 MoE 的数学等价性。</li></ul><h4 id="_2-4-2-控制面-quota-driven-求解" tabindex="-1">2.4.2 控制面：quota-driven 求解 <a class="header-anchor" href="#_2-4-2-控制面-quota-driven-求解" aria-label="Permalink to “2.4.2 控制面：quota-driven 求解”">​</a></h4><p>它不做「先定布局、再定重路由」的两段式，而是<strong>直接求解重路由后每个专家实例收到的负载（quota）</strong>， 把两个阶段耦合起来。内核 <code>quota_placement_solve_kernel</code> 的骨架是「对最优全局负载阈值做二分」， 并且先做一次快速线性探测（<code>fast_step</code>）再二分收窄；<code>do_binary_search</code> 的触发条件是 「本 rank 有冗余专家且 NVL 域内多于一个 rank」。</p><p>可调参数集中在 <code>UltraEPTuning</code>（均有环境变量，括号内为默认值）：</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>参数</th><th>作用</th></tr></thead><tbody><tr><td><code>ULTRA_EP_BALANCE_THRESHOLD</code>（1.0）</td><td>均衡阈值下界</td></tr><tr><td><code>ULTRA_EP_QUOTA_MIN_TOKENS_PER_REPLICA</code>（1024）</td><td><strong>避免为几十个 token 触发一次昂贵的权重复制</strong></td></tr><tr><td><code>ULTRA_EP_QUOTA_LOCALITY_AWARE</code>（True）</td><td>复制时考虑局部性</td></tr><tr><td><code>ULTRA_EP_QUOTA_ALLOW_ZERO_MASTER_QUOTA</code>（False）</td><td>是否允许主专家 quota 归零</td></tr><tr><td><code>ULTRA_EP_QUOTA_ORACLE_EPS</code>（0.01）/ <code>ULTRA_EP_QUOTA_KERNEL_STAGE</code>（1）</td><td>求解精度与内核阶段</td></tr><tr><td><code>ULTRA_EP_GRAD_REDUCE_NUM_SMS</code>（42，须为偶数）/ <code>..._DETERMINISTIC</code>（True）</td><td>归约的 SM 占用与确定性</td></tr><tr><td><code>ULTRA_EP_WEIGHT_SYNC_PLAN_MODE</code>（adaptive）</td><td>权重分发模式：<code>direct</code> / <code>adaptive</code> / <code>force_relay</code></td></tr></tbody></table></div><h4 id="_2-4-3-放置规则与确定性" tabindex="-1">2.4.3 放置规则与确定性 <a class="header-anchor" href="#_2-4-3-放置规则与确定性" aria-label="Permalink to “2.4.3 放置规则与确定性”">​</a></h4><p>默认（非 legacy）放置算法：</p><ol><li><strong>主专家位置固定不动</strong>；</li><li>在每个 NVL 域内贪心复制最热的专家；</li><li>用 LPT 装箱把副本分配到 GPU 槽位，<strong>副本绝不与它的主专家同卡</strong>。</li></ol><p>测试把它固化为不变量：<code>l2p[:, 0]</code> 必须是主专家、副本不得跨越 NVL 域 （违例直接断言 <code>&quot;replica crosses NVL domain&quot;</code>）。且<strong>所有 rank 各自算出相同结果，不需要广播</strong>—— 与 SGLang 的 LPLB 设计一致。</p><p>重路由语义是<strong>确定性轮转</strong>：逻辑专家 <code>l</code> 的第 k 个 token 分派到 <code>l2p[l, k % C_l]</code>（<code>C_l</code> 为该逻辑专家的物理实例数）。</p><h4 id="_2-4-4-数据面" tabindex="-1">2.4.4 数据面 <a class="header-anchor" href="#_2-4-4-数据面" aria-label="Permalink to “2.4.4 数据面”">​</a></h4><ul><li><strong>persistent kernel + 共享内存双缓冲</strong>：把专家权重/梯度切成 tile，用 memory semantics + TMA 做设备间异步搬运；</li><li><strong>chunk streaming relay</strong>：热专家副本多、冷专家无需副本，于是热专家所在 rank 的出向组播会成为新瓶颈。 方案是按实时流量分布构建<strong>两级中继树</strong>，让低流量 rank 帮忙转发；并按 chunk 流式转发， 避免全局 barrier 与通信气泡。相关旋钮：<code>weight_sync_relay_min_replicas / max_relays / min_fanout_gain</code>；</li><li><strong>确定性梯度归约</strong>：用保序累加替代 <code>atomicAdd</code>，保证 FP32 归约可复现；</li><li>通过环境变量控制通信 kernel 的 SM 占用与共享内存足迹，让通信与计算 CTA 能调度到同一 SM 上共存。</li></ul><h4 id="_2-4-5-生命周期" tabindex="-1">2.4.5 生命周期 <a class="header-anchor" href="#_2-4-5-生命周期" aria-label="Permalink to “2.4.5 生命周期”">​</a></h4><p>前向三步（<code>update_placement</code> → <code>weight_sync</code> → <code>reroute</code>）：规划与权重复制在关键路径上， 重路由较轻、基本能被权重复制掩盖。</p><p>反向两步：在 MoE Dgrad 之前用 <code>RestoreReplicaWeights</code>（autograd 恒等前向 + 反向触发权重重分发） 恢复对应 microbatch 的副本布局；在 Wgrad 之前 <code>grad_reduce</code> 把副本梯度归约回主专家， 该通信可藏在 router 与 attention 的反向之后。</p><p>PP/VPP 支持：给每个 <code>(真实层, microbatch slot)</code> 分配<strong>虚层 ID</strong> （<code>num_alloc_layers = real_num_alloc_layers * max_microbatches</code>，且 <code>real_num_alloc_layers = num_layers + 3</code> 为 1-based 层号做 padding），避免布局表与重路由缓冲在 microbatch 间串扰。</p><p>官方注脚同时承认：在开源的 Megatron patch 里，<strong>权重复制被放在 MoE Wgrad 之前</strong> （因为与 fused grouped-GEMM 重叠需要在 kernel 内插入同步，过于侵入）， 所以反向的权重分发并没有被完全掩盖。</p><h4 id="_2-4-6-对外接口" tabindex="-1">2.4.6 对外接口 <a class="header-anchor" href="#_2-4-6-对外接口" aria-label="Permalink to “2.4.6 对外接口”">​</a></h4><p><code>Manager</code> 构造参数包含 <code>num_layers</code>、<code>num_local_master_experts</code>、<code>num_local_redundant_experts</code>、 <code>expert_fc1_numel</code> / <code>expert_fc2_numel</code>（含 FP8 的 scale numel）、<code>is_train</code>、<code>max_microbatches</code>、 <code>legacy_placement</code>、权重/scale 的 dtype；<strong>梯度 dtype 目前只支持 FP32</strong>（否则直接 <code>ValueError</code>）。</p><p>主要方法：<code>construct_local_master_ptr_pool</code>（逐层注册主专家权重/梯度指针）、 <code>update_placement</code> / <code>update_placement_sparse</code>、<code>reroute</code> / <code>reroute_sparse</code>、 <code>weight_sync</code>、<code>grad_reduce</code>、<code>set_weight_sync_plan_mode</code>、<code>set_grad_reduce_deterministic</code>、 <code>allocate_microbatch_slot</code>、<code>get_comm_stream</code>、<code>destroy</code>。</p><h4 id="_2-4-7-性能与集成现状" tabindex="-1">2.4.7 性能与集成现状 <a class="header-anchor" href="#_2-4-7-性能与集成现状" aria-label="Permalink to “2.4.7 性能与集成现状”">​</a></h4><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>指标</th><th>数值</th><th>来源</th></tr></thead><tbody><tr><td>训练吞吐（vs 理想）</td><td>94.6%</td><td>官方博客</td></tr><tr><td>训练 + 推理平均（vs 理想）</td><td>94.3%</td><td>论文摘要</td></tr><tr><td>训练吞吐（vs Megatron-LM）</td><td>+42%</td><td>官方博客</td></tr><tr><td>推理 prefill（vs 理想）</td><td>90%–97%</td><td>官方博客</td></tr><tr><td>推理 prefill（vs SGLang）</td><td>1.56×</td><td>官方博客</td></tr><tr><td>跨 rank 不均衡</td><td>1.30–4.01 → <strong>1.01–1.04</strong></td><td>论文摘要</td></tr><tr><td>关键路径额外开销</td><td>&lt; 300 µs（EP64，占端到端 1%–2%）</td><td>官方博客</td></tr><tr><td>求解耗时</td><td>&lt; 100 µs（EP64）</td><td>官方博客</td></tr><tr><td>评测规模</td><td>至 256 GPU、106B–671B 模型；生产 288B ≥ 92% 理想</td><td>论文摘要 / 博客</td></tr></tbody></table></div><p>集成：参考实现是 <a href="https://github.com/Dots-Infra/Megatron-LM-UltraEP" target="_blank" rel="noreferrer">Megatron-LM 分支</a>， 依赖 <strong>HybridEP</strong>（DeepEP V1 的 <code>hybrid-ep</code> 分支，且需在 <code>setup.py</code> 中打补丁禁用 legacy NVSHMEM 依赖）， <strong>DeepEP V2 支持仍在测试</strong>；SGLang 推理集成为实验特性；提供 8×Hopper 可跑的 demo （32 个 Qwen3-235B 级专家、top-k 4、20 层）与 Qwen3-235B 配方。</p><p>官方的负载 profiler 可逐层、逐 microbatch、逐 EP 组记录重路由前后的专家负载， 并带 HTML 可视化；但<strong>不兼容 CUDA Graph</strong>（用融合元数据内核 + 异步 D2H 把开销压到接近零）。</p><h4 id="_2-4-8-局限" tabindex="-1">2.4.8 局限 <a class="header-anchor" href="#_2-4-8-局限" aria-label="Permalink to “2.4.8 局限”">​</a></h4><ol><li>NVIDIA-only（NVSHMEM），且以 <strong>RSN（rack-scale node）</strong> 为大前提——复制限定在 scale-up 域内；</li><li>依赖 HybridEP 分支与源码补丁，DeepEP V2 路径尚未验证；</li><li>反向的权重分发在开源 patch 中未被掩盖（见 3.4.5 注脚）；</li><li>profiler 不兼容 CUDA Graph；<code>ULTRA_EP_LOAD_PROFILING</code> 与 <code>legacy_placement</code> 互斥（构造时断言）；</li><li>官方自陈：UltraEP 解决的是「跨 rank 不均衡」，与理想上限的残余差距来自<strong>单个专家内部负载不均</strong> 与冗余专家带来的控制开销，而不是残余失衡或关键路径开销。</li></ol><h3 id="_2-5-横向取舍" tabindex="-1">2.5 横向取舍 <a class="header-anchor" href="#_2-5-横向取舍" aria-label="Permalink to “2.5 横向取舍”">​</a></h3><p>把四者放在一起，取舍其实只有三个维度：</p><p><strong>① 预测还是精确。</strong> EPLB 押「负载平稳」，代价是分布漂移时失效；UltraEP 押「每条关键路径都算得起」， 代价是必须把求解压到约 100 µs 并把复制限定在高带宽域；MoonEP 落在中间——逐层精确， 但用固定 <code>S×K</code> 的形状换掉了所有动态形状问题。</p><p><strong>② 动布局还是动 token。</strong> EPLB 只动布局，所以重排是「停世界」的（vLLM / vllm-ascend 需要额外的异步 worker 正源于此）；LPLB / MoonEP / UltraEP 都动 token，因此可以在 microbatch 粒度做， 但必须处理重路由的反向传播与梯度归约。</p><p><strong>③ 副本预算。</strong> EPLB 无上限（<code>num_replicas</code> 自由），极端不均衡下表现最好； LPLB 每专家恰好 1 个副本（<code>max_logcnt == 2</code>），结构最简单、权重复制最好做； MoonEP / UltraEP 的副本数由每 rank 预留 slot 数决定，内存与通信可控，但必须靠跨层复用缓冲摊薄成本。</p><p>一句话总结演进逻辑：<strong>EPLB 是「算得准就能省」，LPLB 是「算得勤就能省」， MoonEP 是「让负载不影响延迟」，UltraEP 是「让精确计算便宜到可以每层都做」。</strong></p><h2 id="附录-信息来源" tabindex="-1">附录：信息来源 <a class="header-anchor" href="#附录-信息来源" aria-label="Permalink to “附录：信息来源”">​</a></h2><p>外部资料均为对应仓库 <code>HEAD</code> 的 README 或设计文档（抓取于 2026-10-10）：</p><ul><li>DeepEP：<a href="https://github.com/deepseek-ai/DeepEP" target="_blank" rel="noreferrer">https://github.com/deepseek-ai/DeepEP</a>（V2.5 变更、<code>EPBuffer</code> 接口、Expert load balancing 一节）</li><li>DeepEP-Ascend：<a href="https://github.com/deepseek-ai/DeepEP-Ascend" target="_blank" rel="noreferrer">https://github.com/deepseek-ai/DeepEP-Ascend</a>（性能表、Ascend 支持矩阵、Ongoing 一节）</li><li>MoonEP：<a href="https://github.com/MoonshotAI/MoonEP" target="_blank" rel="noreferrer">https://github.com/MoonshotAI/MoonEP</a>（Supported Devices、API walkthrough）</li><li>UltraEP：<a href="https://github.com/Dots-Infra/UltraEP" target="_blank" rel="noreferrer">https://github.com/Dots-Infra/UltraEP</a>（v1.0.0 release note、接口与集成；技术报告 <code>docs/blog_v1.md</code>）</li><li>UltraEP 论文：<a href="https://arxiv.org/abs/2606.04101" target="_blank" rel="noreferrer">https://arxiv.org/abs/2606.04101</a>（摘要与评测口径）</li><li>EPLB：<a href="https://github.com/deepseek-ai/EPLB" target="_blank" rel="noreferrer">https://github.com/deepseek-ai/EPLB</a>（分层 / 全局策略、<code>rebalance_experts</code>）</li><li>LPLB：<a href="https://github.com/deepseek-ai/LPLB" target="_blank" rel="noreferrer">https://github.com/deepseek-ai/LPLB</a>（边容量 LP 模型、拓扑与限制）</li><li>vLLM EPLB：<a href="https://github.com/vllm-project/vllm" target="_blank" rel="noreferrer">https://github.com/vllm-project/vllm</a>（<code>docs/serving/expert_parallel_deployment.md</code>、<code>vllm/distributed/eplb/</code>）</li><li>vLLM-Ascend EPLB：<a href="https://github.com/vllm-project/vllm-ascend" target="_blank" rel="noreferrer">https://github.com/vllm-project/vllm-ascend</a>（EPLB 用户指南与 Model Runner V2 设计文档）</li><li>SGLang：<a href="https://github.com/sgl-project/sglang" target="_blank" rel="noreferrer">https://github.com/sgl-project/sglang</a>（<code>python/sglang/srt/eplb/</code>、<code>test/registered/npu/</code>、昇腾支持矩阵）</li><li>sgl-kernel-npu（SGLang 昇腾 DeepEP 兼容库）：<a href="https://github.com/sgl-project/sgl-kernel-npu" target="_blank" rel="noreferrer">https://github.com/sgl-project/sgl-kernel-npu</a></li><li>MindSpeed：<a href="https://github.com/Ascend/MindSpeed" target="_blank" rel="noreferrer">https://github.com/Ascend/MindSpeed</a>（<code>docs/zh/features/moe_expert_load_balance_placeemnt.md</code> —上游文件名如此拼写、<code>docs/zh/features/balanced_moe.md</code>、<code>moe/expert_placement/</code>）</li><li>Megatron-LM：<a href="https://github.com/NVIDIA/Megatron-LM" target="_blank" rel="noreferrer">https://github.com/NVIDIA/Megatron-LM</a>（<code>megatron/core/transformer/moe/README.md</code>）</li></ul><h2 id="相关阅读" tabindex="-1">相关阅读 <a class="header-anchor" href="#相关阅读" aria-label="Permalink to “相关阅读”">​</a></h2><ul><li><a href="/llmtechsite/ascend/ecosystem/moonep">MoonEP：动态冗余专家与专家并行通信</a></li><li><a href="/llmtechsite/ascend/ecosystem/moonep-hyperparallel-training">MoonEP 集成 HyperParallel：端到端训练与 all-to-all 对比</a></li></ul>`,118)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};